<?php
require_once __DIR__.'/../includes/admin.php';admin_required();if($_SERVER['REQUEST_METHOD']!=='POST')exit('Méthode non autorisée.');verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id){flash('Produit invalide.','error');redirect('index.php');}$st=db()->prepare('SELECT image FROM products WHERE id=?');$st->execute([$id]);$p=$st->fetch();if(!$p){flash('Produit introuvable.','error');redirect('index.php');}try{$st=db()->prepare('DELETE FROM products WHERE id=?');$st->execute([$id]);if($p['image']&&str_starts_with($p['image'],'uploads/'))@unlink(dirname(__DIR__).'/'.$p['image']);flash('Produit supprimé.');}catch(PDOException$e){if($e->getCode()==='23000'){db()->prepare('UPDATE products SET is_active=0 WHERE id=?')->execute([$id]);flash('Produit archivé car il appartient à une commande.');}else flash('Impossible de supprimer.','error');}redirect('index.php');
